import { tags } from "typia";

/**
 * Aggregated seller dashboard overview containing account status, storefront details, and business metrics.
 *
 * This view consolidates the authenticated seller's operational snapshot in a single response, including their platform approval status and rejection details, active shop profile information, and key performance metrics such as product counts, order volumes, and pending customer requests.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IEcommercePlatformSellerDashboard = {
  /**
   * The current platform approval status of the seller account.
   *
   * Indicates whether the seller registration is awaiting administrator review ('pending'), has been granted full selling privileges ('approved'), or was denied ('rejected'). Only sellers with 'approved' status can list products and operate their shop.
   *
     * @x-autobe-specification Mapped from
     *   ecommerce_platform_sellers.approval_status column where id equals
     *   authenticated seller id from JWT. Returns string value: 'pending',
     *   'approved', or 'rejected'.
   */
  approvalStatus: string;

  /**
   * The administrator's explanation for rejecting the seller application.
   *
   * Contains details about why the registration was denied when the seller status is 'rejected'. Returns null for pending or approved accounts.
   *
     * @x-autobe-specification Mapped from
     *   ecommerce_platform_sellers.rejection_reason column where id equals
     *   authenticated seller id from JWT. Nullable string - only populated when
     *   approval_status equals 'rejected'.
   */
  rejectionReason: string | null;

  /**
   * The public-facing business name of the seller's shop.
   *
   * Displayed on product pages, search results, and the seller storefront. Must be unique across all shops on the platform.
   *
     * @x-autobe-specification Mapped from
     *   ecommerce_platform_seller_profiles.shop_name column via JOIN on
     *   seller_id equals authenticated seller id from JWT. Subject to unique
     *   constraint across all seller profiles on the platform.
   */
  shopName: string;

  /**
   * A textual description of the seller's business or product offerings.
   *
   * Visible on the seller profile page to help customers understand the seller's business.
   *
     * @x-autobe-specification Mapped from
     *   ecommerce_platform_seller_profiles.shop_description column via JOIN on
     *   seller_id equals authenticated seller id from JWT.
   */
  shopDescription: string;

  /**
   * The URI of the seller's brand logo image.
   *
   * Displayed alongside the shop name on all platform surfaces where seller identity appears.
   *
     * @x-autobe-specification Mapped from
     *   ecommerce_platform_seller_profiles.logo_image_uri column via JOIN on
     *   seller_id equals authenticated seller id from JWT. Maximum length 80000
     *   characters.
   */
  logoImageUri: string;

  /**
   * The total number of active product listings owned by the seller.
   *
   * Only counts products that are not soft-deleted. Provides a quick metric for catalog size.
   *
     * @x-autobe-specification Computed aggregation: COUNT(*) FROM
     *   ecommerce_platform_products WHERE seller_profile_id = authenticated
     *   seller's profile id AND deleted_at IS NULL. Excludes soft-deleted
     *   products.
   */
  totalProducts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * The total number of order items purchased from the seller's products.
   *
   * Counts every line item across all customer orders containing the seller's product variants. Each line item counts as one regardless of quantity.
   *
     * @x-autobe-specification Computed aggregation: COUNT(*) FROM
     *   ecommerce_platform_order_items joined through product variants and
     *   products to the seller's profile. Counts all line items where customers
     *   purchased the seller's product variants.
   */
  totalOrderItems: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * The number of customer cancellation requests awaiting seller decision.
   *
   * These are pending requests from customers to cancel order items, requiring the seller to approve or reject.
   *
     * @x-autobe-specification Computed aggregation: COUNT(*) FROM
     *   ecommerce_platform_cancellation_requests WHERE status = 'pending' AND
     *   the request's order_item references a product variant owned by the
     *   authenticated seller.
   */
  totalPendingCancellationRequests: number &
    tags.Type<"int32"> &
    tags.Minimum<0>;

  /**
   * The number of customer refund requests awaiting seller decision.
   *
   * These are pending refund claims for delivered items, requiring the seller to review and approve or reject.
   *
     * @x-autobe-specification Computed aggregation: COUNT(*) FROM
     *   ecommerce_platform_refund_requests WHERE status = 'pending' AND the
     *   request's order_item references a product variant owned by the
     *   authenticated seller.
   */
  totalPendingRefundRequests: number & tags.Type<"int32"> & tags.Minimum<0>;
};
